<script lang="ts">
 import {onMount} from 'svelte';let {onEquipment}=$props<{onEquipment:(id:string)=>void}>();let feeds:any[]=$state([]);let status=$state('loading');let message=$state('');let refreshing=$state(false);
 async function load(){if(refreshing)return;refreshing=true;try{const r=await fetch('/api/home/feeds');if(!r.ok)throw new Error('Feed sync unavailable');const data=await r.json();feeds=data.feeds??[];status=data.status;message='';}catch(e){message=e instanceof Error?e.message:String(e);status='sync-error';}finally{refreshing=false;}}
 onMount(()=>{load();const timer=setInterval(load,30000);return ()=>clearInterval(timer);});
</script>
<section><h2>Device observations</h2><p>Read through Fulcra, refreshed every 30 seconds while this section is open. A recent report is not proof of physical function.</p><button onclick={load} disabled={refreshing}>{refreshing?'Syncing…':'Refresh observations'}</button>
 {#if status==='unconfigured'}<p>No device feeds are configured. Your equipment inventory is not a live reading. A connected local agent can publish authorized observations to a home-specific Fulcra data type.</p>{/if}
 {#if status==='sync-error'}<p class="warning">{message}. Previously displayed values are not newly verified.</p>{/if}
 {#each feeds as feed}<article><p class="eyebrow">{feed.state}{feed.latest?.synthetic?' · SYNTHETIC VERIFICATION':''}</p><h3>{feed.name}</h3>{#if feed.equipmentId}<button onclick={()=>onEquipment(feed.equipmentId)}>Equipment record</button>{/if}{#if feed.latest}<p class="value">{feed.latest.value??'Value unavailable'} {feed.latest.unit??''}</p><p>Device observed: {feed.latest.observedAt??'timestamp unknown'}</p><p>Bridge received (reported): {feed.latest.receivedAt??'timestamp unknown'}</p><p>Fulcra record time: {feed.latest.fulcraRecordedAt??'not available'}</p><p>Device availability: {feed.latest.availability}</p>{:else}<p>No usable observation in the last 24 hours. This does not establish the device’s current state.</p>{/if}<p>Last sync: {feed.syncedAt}</p><p>Fulcra source: {feed.sourceName??feed.dataType??'unavailable'}</p>{#if feed.latest}<p>Source event ID: {feed.latest.id}</p>{/if}{#if feed.detail}<p>{feed.detail}</p>{/if}{#if feed.conflictCount}<p class="warning">Conflicting event IDs require review.</p>{/if}</article>{/each}
</section>
<style>section{margin:30px 0}h2{font-size:25px}p{line-height:1.6}article{background:white;border:1px solid #dbe4df;padding:22px;border-radius:12px;margin:20px 0}.eyebrow{text-transform:uppercase;font-size:12px;color:#387367}.value{font-size:30px;font-weight:650}.warning{color:#8d431d}button{padding:10px 16px;border:1px solid #cadbd1;border-radius:8px;background:white;color:#254a3c;cursor:pointer}</style>
